var builder = WebApplication.CreateBuilder(args);

// Redis
builder.Services.AddStackExchangeRedisCache(options =>
    options.Configuration = builder.Configuration.GetConnectionString("cache"));

// Database
builder.Services.AddDbContext<AppDbContext>(options =>
    options.UseNpgsql(builder.Configuration.GetConnectionString("nexus-db")));

// RabbitMQ
builder.Services.AddRabbitMq(builder.Configuration.GetConnectionString("messaging"));

// OpenAI (non-secret, passed via environment)
builder.Services.AddSingleton(sp => new OpenAIClient(
    new OpenAIClientSettings
    {
        Endpoint = new Uri(builder.Configuration["AI:Azure:Endpoint"]),
        ApiKey = builder.Configuration["AI:Azure:Key"]
    }));

var app = builder.Build();
app.MapHealthChecks("/");
app.Run();

public class OpenAiHealthCheck : IHealthCheck
{
    private readonly OpenAIClient _client;

    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context, CancellationToken ct = default)
    {
        try
        {
            // Lightweight model info call to verify connectivity
            var models = await _client.Models.ListAsync(ct);
            var response = models.First();
            return HealthCheckResult.Healthy($"OpenAI reachable, model: {response.Id}");
        }
        catch (AuthenticationException ex)
        {
            return new HealthCheckResult(
                HealthStatus.Degraded, "Invalid API key", ex);
        }
        catch (Exception ex)
        {
            return new HealthCheckResult(
                HealthStatus.Unhealthy, "OpenAI unreachable", ex);
        }
    }
}

// Register in DI
builder.Services.AddHealthChecks()
    .AddCheck<OpenAiHealthCheck>("openai", tags: ["ai", "llm"]);
